powerpagecomponent.content:
{
  "source": "{% assign appId = request.params['record'] | default: request.params['id'] %}

{% fetchxml sectionJsonSchema %}
<fetch>
  <entity name="cmdspp_pc_enrol_page_json_tb">
    <attribute name="cmdspp_p_jsontxt" />
    <attribute name="cmdspp_p_table_nam" />
    <attribute name="cmdspp_p_page_nam" />
    <filter>
      <condition attribute="cmdspp_p_page_nam"
                 operator="eq"
                 value="Provider_Identifier_Number" />
    </filter>
  </entity>
</fetch>
{% endfetchxml %}

{% assign deaSchemaJson = '' %}
{% assign otherStateSchemaJson = '' %}
{% assign mcpSchemaJson = '' %}
{% assign otmSchemaJson = '' %}

{% for rec in sectionJsonSchema.results.entities %}
  {% if rec.cmdspp_p_table_nam == 'cmdspp_p_pin_dea_dtls' %}
    {% assign deaSchemaJson = rec.cmdspp_p_jsontxt %}
  {% endif %}
  {% if rec.cmdspp_p_table_nam == 'cmdspp_p_pin_oth_smpi_dtls' %}
    {% assign otherStateSchemaJson = rec.cmdspp_p_jsontxt %}
  {% endif %}
  {% if rec.cmdspp_p_table_nam == 'cmdspp_p_pin_mcp_dtls' %}
    {% assign mcpSchemaJson = rec.cmdspp_p_jsontxt %}
  {% endif %}
  {% if rec.cmdspp_p_table_nam == 'cmdspp_p_pin_mcp_on_dtls' %}
    {% assign otmSchemaJson = rec.cmdspp_p_jsontxt %}
  {% endif %}
{% endfor %}

{% assign deaFormData = deaSchemaJson | parse_json %}
{% assign otherStateFormData = otherStateSchemaJson | parse_json %}
{% assign mcpFormData = mcpSchemaJson | parse_json %}
{% assign otmFormData = otmSchemaJson | parse_json %}

{% comment %} --- Resolve safe JS-ready fallbacks, no braces inside {{ }} tags --- {% endcomment %}
{% assign emptyJsonObj = '{}' %}

{% assign deaSchemaJsonOut = deaSchemaJson | strip_newlines %}
{% if deaSchemaJsonOut == blank %}{% assign deaSchemaJsonOut = emptyJsonObj %}{% endif %}

{% assign otherStateSchemaJsonOut = otherStateSchemaJson | strip_newlines %}
{% if otherStateSchemaJsonOut == blank %}{% assign otherStateSchemaJsonOut = emptyJsonObj %}{% endif %}

{% assign mcpSchemaJsonOut = mcpSchemaJson | strip_newlines %}
{% if mcpSchemaJsonOut == blank %}{% assign mcpSchemaJsonOut = emptyJsonObj %}{% endif %}

{% assign otmSchemaJsonOut = otmSchemaJson | strip_newlines %}
{% if otmSchemaJsonOut == blank %}{% assign otmSchemaJsonOut = emptyJsonObj %}{% endif %}

<div class="cmdspp-form-body d-flex flex-column">

  <!-- ACCORDION 1: DEA  -->
  <div class="accordion-container" id="section-dea">
    <fieldset class="active">
      <legend>
        <div class="accordion-header">
          <div class="accordion-title">
            <span class="step-circle">a</span>
            <span>DEA</span>
          </div>
          <span class="accordion-arrow active"></span>
        </div>
      </legend>

      <div class="accordion-content">
        <div class="p-3 mb-4 border rounded bg-light">
          {% include 'cmdspp_RenderFormFields', formData: deaFormData %}
        </div>

        <div class="mb-2" id="deaTableWrapper">
          {% include 'cmdspp_Enrollment-PP-commonTable', tableId: 'dea' %}
        </div>

        <div class="d-flex justify-content-between align-items-center pt-3 border-top">
          <button type="button" id="btnResetDea" class="btn-reset-custom">Reset</button>
          <div class="d-flex gap-2">
            <button type="button" id="deaContinueBtn" class="btn-continue-custom" data-current="section-dea">Continue</button>
          </div>
        </div>
      </div>
    </fieldset>
  </div>

  <!-- ACCORDION: OTHER STATE MEDICAID PROGRAM INFORMATION  -->
  <div class="accordion-container" id="section-otherstate">
    <fieldset>
      <legend>
        <div class="accordion-header">
          <div class="accordion-title">
            <span class="step-circle">b</span>
            <span>Other State Medicaid Program Information</span>
          </div>
          <span class="accordion-arrow"></span>
        </div>
      </legend>

      <div class="accordion-content" style="display: none;">
        <div class="p-3 mb-4 border rounded bg-light">
          {% include 'cmdspp_RenderFormFields', formData: otherStateFormData %}
        </div>

        <div class="d-flex justify-content-between align-items-center pt-3 border-top">
          <button type="button" id="btnResetOtherState" class="btn-reset-custom">Reset</button>
          <div class="d-flex gap-2">
            <button type="button" id="btnBackOtherState" class="btn-back-custom" data-previous="section-dea">Back</button>
            <button type="button" id="otherStateContinueBtn" class="btn-continue-custom" data-current="section-otherstate">Continue</button>
          </div>
        </div>
      </div>
    </fieldset>
  </div>

  <!--  ACCORDION 2: MEDICARE CROSSOVER PAYMENT -->
  <div class="accordion-container" id="section-mcp">
    <fieldset>
      <legend>
        <div class="accordion-header">
          <div class="accordion-title">
            <span class="step-circle">c</span>
            <span>Medicare Crossover Payment - Medicare</span>
          </div>
          <span class="accordion-arrow"></span>
        </div>
      </legend>

      <div class="accordion-content" style="display: none;">
        <div class="p-3 mb-4 border rounded bg-light">
          {% include 'cmdspp_RenderFormFields', formData: mcpFormData %}
        </div>

        <div class="mb-2" id="mcpTableWrapper">
          {% include 'cmdspp_Enrollment-PP-commonTable', tableId: 'mcp' %}
        </div>

        <div class="d-flex justify-content-between align-items-center pt-3 border-top">
          <button type="button" id="btnResetMcp" class="btn-reset-custom">Reset</button>
          <div class="d-flex gap-2">
            <button type="button" id="btnBackMcp" class="btn-back-custom" data-previous="section-otherstate">Back</button>
            <button type="button" id="mcpContinueBtn" class="btn-continue-custom" data-current="section-mcp">Continue</button>
          </div>
        </div>
      </div>
    </fieldset>
  </div>

  <!-- ACCORDION: OTHER MEDICARE NUMBERS -->
  <div class="accordion-container" id="section-otm">
    <fieldset>
      <legend>
        <div class="accordion-header">
          <div class="accordion-title">
            <span class="step-circle">d</span>
            <span>Medicare Crossover Payment - Other Medicare Numbers</span>
          </div>
          <span class="accordion-arrow"></span>
        </div>
      </legend>

      <div class="accordion-content" style="display: none;">
        <div class="p-3 mb-4 border rounded bg-light">
          {% include 'cmdspp_RenderFormFields', formData: otmFormData %}
        </div>

        <div class="mb-2" id="otmTableWrapper">
          {% include 'cmdspp_Enrollment-PP-commonTable', tableId: 'otm' %}
        </div>

        <div class="d-flex justify-content-between align-items-center pt-3 border-top">
          <button type="button" id="btnResetOtm" class="btn-reset-custom">Reset</button>
          <div class="d-flex gap-2">
            <button type="button" id="btnBackOtm" class="btn-back-custom" data-previous="section-mcp">Back</button>
            <button type="button" id="otmContinueBtn" class="btn-continue-custom" data-current="section-otm">Continue</button>
          </div>
        </div>
      </div>
    </fieldset>
  </div>

</div>



<script>
(function () {
  "use strict";

  var parentAppGuid = getUrlParameter("record") || getUrlParameter("id");
  var CREATED_BY_USER_ENTITY_SET = "cmdspp_g_usr_dtls_tbs";

  /*
   * DYNAMIC PAGE CONFIGURATION
   */
var pageJson = [
    JSON.parse(`{{ deaSchemaJsonOut }}`),
    JSON.parse(`{{ otherStateSchemaJsonOut }}`),
    JSON.parse(`{{ mcpSchemaJsonOut }}`),
    JSON.parse(`{{ otmSchemaJsonOut }}`)
];

  var sections = {};
  pageJson.forEach(function (section) {
    sections[section.sectionId] = section;
    if (section.isSingleRecord) {
      section.record = { recordId: null, dbId: null, isNew: true };
      section.savedRecord = null;
    } else {
      section.records = [];
    }
  });

  function getUrlParameter(name) {
    var regex = new RegExp("[\\?&]" + name + "=([^&#]*)");
    var results = regex.exec(location.search);
    return results === null ? "" : decodeURIComponent(results[1].replace(/\+/g, " "));
  }

  function getPortalContactId() {
    try { return window.cmdsppUserId || null; } catch (e) { return null; }
  }
  var currentContactId = getPortalContactId();

  function withCreatedByUser(payload) {
    if (currentContactId) {
      payload["cmdspp_created_by_user@odata.bind"] = "/" + CREATED_BY_USER_ENTITY_SET + "(" + currentContactId + ")";
    }
    return payload;
  }

  /*
   * POWER PAGES WEB API
   */
  (function (webapi, $) {
    function getTokenAsync() {
      var deferred = $.Deferred();
      if (typeof shell !== "undefined" && typeof shell.getTokenDeferred === "function") {
        shell.getTokenDeferred().done(function (token) { deferred.resolve(token); })
          .fail(function () { fetchServerToken(deferred); });
      } else {
        fetchServerToken(deferred);
      }
      return deferred.promise();
    }
    function fetchServerToken(deferred) {
      var domToken = $('input[name="__RequestVerificationToken"]').val();
      $.ajax({ type: "GET", url: "/_services/auth/token", cache: false })
        .done(function (token) { deferred.resolve(token || domToken || ""); })
        .fail(function () { deferred.resolve(domToken || ""); });
    }
    function safeAjax(ajaxOptions) {
      var deferred = $.Deferred();
      getTokenAsync().done(function (token) {
        ajaxOptions.headers = ajaxOptions.headers || {};
        if (token) {
          ajaxOptions.headers["__RequestVerificationToken"] = token;
          ajaxOptions.headers["RequestVerificationToken"] = token;
        }
        $.ajax(ajaxOptions)
          .done(function (data, textStatus, jqXHR) { deferred.resolve(data, textStatus, jqXHR); })
          .fail(function (jqXHR, textStatus, errorThrown) { deferred.reject(jqXHR, textStatus, errorThrown); });
      });
      return deferred.promise();
    }
    webapi.safeAjax = safeAjax;
  })(window.webapi = window.webapi || {}, jQuery);

  function extractIdFromResponse(jqXHR) {
    try {
      var header = jqXHR && (jqXHR.getResponseHeader("OData-EntityId") || jqXHR.getResponseHeader("odata-entityid"));
      if (header) {
        var match = header.match(/\(([^)]+)\)/);
        if (match) return match[1];
      }
    } catch (e) { console.warn("Could not extract record ID", e); }
    return null;
  }

  function newRecordId() {
    return "new-" + Date.now() + "-" + Math.floor(Math.random() * 100000);
  }

  // cmdspp_RenderFormFields registers window.cmdsppForms[containerId] only after its
  // own async option-loading finishes, so poll briefly rather than assuming it's ready.
  function waitForForm(containerId, callback, attemptsLeft) {
    attemptsLeft = attemptsLeft === undefined ? 40 : attemptsLeft;
    var form = window.cmdsppForms && window.cmdsppForms[containerId];
    if (form) { callback(form); return; }
    if (attemptsLeft <= 0) { console.warn("Form never became ready:", containerId); return; }
    setTimeout(function () { waitForForm(containerId, callback, attemptsLeft - 1); }, 50);
  }

  /* =========================================================
   * NEW: INLINE MESSAGE HELPER (replaces alert()/confirm())
   * Shows a small inline status message next to a section's
   * Continue button instead of a blocking browser dialog.
   * ========================================================= */
  function showSectionMessage(section, message, isError) {
    var button = document.getElementById(section.submitBtnId);
    if (!button || !button.parentNode) return;

    var existing = button.parentNode.querySelector(".cmdspp-section-message[data-for='" + section.submitBtnId + "']");
    if (existing) existing.remove();

    if (!message) return;

    var msgEl = document.createElement("span");
    msgEl.className = "cmdspp-section-message";
    msgEl.setAttribute("data-for", section.submitBtnId);
    msgEl.style.cssText = "font-size:12px;margin-right:12px;align-self:center;color:" + (isError ? "#c50f12" : "#1AA3A3") + ";";
    msgEl.textContent = message;
    button.parentNode.insertBefore(msgEl, button);
  }

  /*
   * OPTIONS MAP (guid -> label) FOR MULTISELECT / CHECKBOXGROUP FIELDS
   */
  var optionsMapCache = {};
  function fetchOptionsMap(source) {
    var deferred = $.Deferred();
    if (!source) { deferred.resolve({}); return deferred.promise(); }

    if (optionsMapCache[source.domainVal]) {
      deferred.resolve(optionsMapCache[source.domainVal]);
      return deferred.promise();
    }

    var filter = source.domainName + " eq '" + source.domainVal + "'";
    var select = source.valueField + "," + source.labelField;
    var url = "/_api/" + source.table + "?$select=" + encodeURIComponent(select) + "&$filter=" + encodeURIComponent(filter);

    webapi.safeAjax({
      type: "GET", url: url, contentType: "application/json",
      headers: { "Accept": "application/json", "OData-MaxVersion": "4.0", "OData-Version": "4.0" }
    }).done(function (data) {
      var map = {};
      (data.value || []).forEach(function (row) { map[row[source.valueField]] = row[source.labelField]; });
      optionsMapCache[source.domainVal] = map;
      deferred.resolve(map);
    }).fail(function (xhr) {
      console.error("Failed to load options map:", source, xhr);
      deferred.resolve({});
    });

    return deferred.promise();
  }

  function loadSectionOptionsMap(section) {
    if (!section.multiSelectField) return $.Deferred().resolve().promise();
    var fieldDef = (section.fields || []).find(function (f) { return f.name === section.multiSelectField; });
    if (!fieldDef || !fieldDef.source) return $.Deferred().resolve().promise();

    return fetchOptionsMap(fieldDef.source).done(function (map) {
      section.optionsMap = map;
      refreshGrid(section);
    });
  }

  /*
   * SECTION HELPERS
   */
  function getSectionByContainerId(containerId) {
    return pageJson.find(function (section) { return section.containerId === containerId; });
  }
  function getSectionByElementId(sectionId) {
    return pageJson.find(function (section) { return section.sectionId === sectionId; });
  }

  function getGridInstance(section) {
      var actions = {
        onDelete: function (record) { deleteRecord(section, record); }
      };

      if (section.sectionId !== "section-dea") {
        actions.onEdit = function (record) { editRecord(section, record); };
      }

      return CommonTableTemplate.getInstance(section.tableId, {
        actions: actions
      });
}

  /* FIX: filter out isDeleted records so a delete is reflected in the
     table immediately, instead of waiting for a reload from Dataverse
     on Continue. */
  function refreshGrid(section) {
    if (section.isSingleRecord) return;

    var rows = (section.records || [])
      .filter(function (record) { return !record.isDeleted; })
      .map(function (record) {
        if (!section.multiSelectField) return record;

        var displayRow = Object.assign({}, record);
        var guid = record.partsGuid || record[section.multiSelectField];

        displayRow[section.multiSelectField] =
          (section.optionsMap && section.optionsMap[guid]) ||
          record.partsLabel ||
          guid || "";

        return displayRow;
      });

    getGridInstance(section).render(section.columns, rows);
  }

  /*
   * EDIT (grid sections only)
   */
  function getEditValues(section, record) {
    var values = {};
    (section.fields || []).forEach(function (field) {
      var name = field.name;
      if (record[name] !== undefined) values[name] = record[name];
    });
    if (section.multiSelectField) {
      var selected = record.partsGuid || record[section.multiSelectField];
      values[section.multiSelectField] = selected ? [selected] : [];
    }
    return values;
  }

  function editRecord(section, record) {
    var form = window.cmdsppForms && window.cmdsppForms[section.containerId];
    if (!form) { console.warn("Form not found:", section.containerId); return; }
    form.setValues(getEditValues(section, record), record.recordId);
    refreshGrid(section);
  }

  /*
   * DELETE (grid sections only) - staged locally until Continue.
   */
 function deleteRecord(section, record) {
  
  var actual = section.records.find(function (r) {
    return String(r.recordId) === String(record.recordId);
  });

  if (!actual) {
    console.warn("Delete target record not found:", record && record.recordId, "in section:", section.sectionId);
    return;
  }

  if (actual.isNew) {
    section.records = section.records.filter(function (r) { return r.recordId !== actual.recordId; });
  } else {
    actual.isDeleted = true;
    actual.isEdited = false;
  }

  refreshGrid(section);
}

  /*
   * FORM SUBMIT (the little "+ Add" / "Update" form inside a
   */
  window.addEventListener("dynamicFormSubmit", function (e) {
    var detail = e.detail || {};
    var section = getSectionByContainerId(detail.containerId);
    if (!section) { console.warn("No section found for:", detail.containerId); return; }

    var values = detail.values || {};
    var isEditing = !!detail.isEditing;
    var editingId = detail.editingId;

    (section.fields || []).forEach(function (f) {
      if (f.transform === "uppercase" && typeof values[f.name] === "string") {
        values[f.name] = values[f.name].toUpperCase();
      }
    });

    if (section.isSingleRecord) {
      Object.assign(section.record, values);
      return;
    }

    if (isEditing) {
                var existing = section.records.find(function (r) {
            return String(r.recordId) === String(editingId) && !r.isDeleted;
          });

          if (!existing) {
            console.warn("Edit target record not found for editingId:", editingId, "in section:", section.sectionId);
            return;
          }

          Object.assign(existing, values);

          if (section.multiSelectField) {
            var selected = values[section.multiSelectField] || [];
            var guid = selected[0] || "";
            existing.partsGuid = guid;
            existing.partsLabel = (section.optionsMap && section.optionsMap[guid]) || guid;
            existing[section.multiSelectField] = guid;
          }

          existing.isEdited = true;
    } else {
      if (section.createMode === "multiSelect") {
        var selectedValues = values[section.multiSelectField] || [];

        var restValues = Object.assign({}, values);
        delete restValues[section.multiSelectField];

        selectedValues.forEach(function (partGuid) {
          section.records.push(Object.assign({
            recordId: newRecordId(),
            dbId: null,
            isNew: true,
            isEdited: false,
            isDeleted: false
          }, restValues, {
            partsGuid: partGuid,
            partsLabel: (section.optionsMap && section.optionsMap[partGuid]) || partGuid
          }));
        });
      } else {
        section.records.push(Object.assign({
          recordId: newRecordId(),
          dbId: null,
          isNew: true,
          isEdited: false,
          isDeleted: false
        }, values));
      }
    }

    refreshGrid(section);
  });

  /*
   * RESET
   */
  function resetGridSection(section) {
    section.records = section.records.filter(function (record) { return !record.isNew; });
    section.records.forEach(function (record) { record.isEdited = false; record.isDeleted = false; });

    var form = window.cmdsppForms && window.cmdsppForms[section.containerId];
    if (form) form.reset();

    showSectionMessage(section, "", false);
    refreshGrid(section);
  }

  function resetSingleRecordSection(section) {
    if (section.savedRecord) {
      section.record = JSON.parse(JSON.stringify(section.savedRecord));
    } else {
      section.record = { recordId: null, dbId: null, isNew: true };
      (section.fields || []).forEach(function (f) {
        section.record[f.name] = Array.isArray(f.value) ? [] : "";
      });
    }

    waitForForm(section.containerId, function (form) { form.setValues(section.record); });
  }

  function bindResetButtons() {
    pageJson.forEach(function (section) {
      var button = document.getElementById(section.resetBtnId);
      if (!button) return;
      button.addEventListener("click", function () {
        if (section.isSingleRecord) resetSingleRecordSection(section);
        else resetGridSection(section);
      });
    });
  }

  /*
   * ACCORDION
   */
  function openAccordionSection(sectionId) {
    document.querySelectorAll(".accordion-container fieldset").forEach(function (fs) { fs.classList.remove("active"); });
    document.querySelectorAll(".accordion-container .accordion-arrow").forEach(function (arrow) { arrow.classList.remove("active"); });
    document.querySelectorAll(".accordion-container .accordion-content").forEach(function (content) { content.style.display = "none"; });

    var target = document.getElementById(sectionId);
    if (!target) return;

    target.querySelector("fieldset").classList.add("active");
    target.querySelector(".accordion-arrow").classList.add("active");
    target.querySelector(".accordion-content").style.display = "block";
  }

  function markSectionCompleted(sectionId) {
    var target = document.getElementById(sectionId);
    if (target) target.querySelector("fieldset").classList.add("completed");
  }

  function bindAccordion() {
    document.querySelectorAll(".accordion-container fieldset legend").forEach(function (legend) {
      legend.addEventListener("click", function () {
        var fieldset = legend.closest("fieldset");
        var content = fieldset.querySelector(".accordion-content");
        var container = fieldset.closest(".accordion-container");

        if (content.style.display === "none" || content.style.display === "") {
          openAccordionSection(container.id);
        } else {
          content.style.display = "none";
          fieldset.classList.remove("active");
          fieldset.querySelector(".accordion-arrow").classList.remove("active");
        }
      });
    });
  }

  /*
   * LOADING STATE
   */
  function setSectionLoading(buttonId, isLoading) {
    var button = document.getElementById(buttonId);
    if (!button) return;

    if (isLoading) {
      button.dataset.originalText = button.textContent;
      button.disabled = true;
      button.textContent = "Saving...";
    } else {
      button.disabled = false;
      button.textContent = button.dataset.originalText || "Continue";
    }
  }

  /*
   * ADD-BUTTON READINESS GUARD
   */
  function disableAddUntilReady(section) {
    if (!section.addBtnId) return;
    var button = document.getElementById(section.addBtnId);
    if (!button) return;

    button.disabled = true;
    var originalLabel = button.textContent;
    button.dataset.originalText = originalLabel;
    button.textContent = "Loading...";

    waitForForm(section.containerId, function () {
      button.disabled = false;
      button.textContent = button.dataset.originalText || originalLabel;
    });
  }

  /*
   * GENERIC DATAVERSE PAYLOAD (create/update)
   */
  function buildPayload(section, record) {
    var payload = {};

    (section.fieldMappings || []).forEach(function (mapping) {
      var value = record[mapping.formField];
      if (mapping.formField === "partsGuid") value = record.partsGuid;

      if (mapping.type === "yesnoBoolean") {
        if (value === "Yes" || value === "No") payload[mapping.dataverseField] = value === "Yes";
        return;
      }

      if (mapping.type === "multiselect") {
        var dependencyMet = !mapping.dependsOn || record[mapping.dependsOn] === "Yes";
        if (!dependencyMet) return;

        var selectedGuids = value || [];
        payload[mapping.dataverseField] = selectedGuids.join(";");
        return;
      }

      if (value === undefined || value === null || value === "") return;

      if (mapping.type === "lookup") {
        payload[mapping.dataverseField + "@odata.bind"] = "/" + mapping.entitySet + "(" + value + ")";
      } else if (mapping.type === "boolean") {
        payload[mapping.dataverseField] = value === true || value === "true";
      } else {
        payload[mapping.dataverseField] = value;
      }
    });

    return payload;
  }

  /*
   * DATAVERSE READ / REFRESH (grid sections)
   */
  function getDataverseSelectFields(section) {
    var fields = [section.recordIdField];
    (section.fieldMappings || []).forEach(function (mapping) {
      if (mapping.type === "lookup") return;
      fields.push(mapping.dataverseField);
    });
    (section.fieldMappings || []).forEach(function (mapping) {
      if (mapping.type !== "lookup") return;
      var fieldName = "_" + mapping.dataverseField + "_value";
      if (fields.indexOf(fieldName) === -1) fields.push(fieldName);
    });
    return fields.join(",");
  }

  function getDataverseLookupValue(raw, fieldName) {
    return raw["_" + fieldName + "_value"] || "";
  }
  function getDataverseLookupLabel(raw, fieldName) {
    return raw["_" + fieldName + "_value@OData.Community.Display.V1.FormattedValue"] || "";
  }

  function mapDataverseRecord(section, raw) {
    var record = {
      recordId: raw[section.recordIdField],
      dbId: raw[section.recordIdField],
      isNew: false,
      isEdited: false,
      isDeleted: false
    };

    (section.fieldMappings || []).forEach(function (mapping) {
      if (mapping.type === "lookup") {
        var guid = getDataverseLookupValue(raw, mapping.dataverseField);
        record[mapping.formField] = guid;
        if (mapping.formField === "partsGuid") {
          record.partsGuid = guid;
          record.partsLabel = getDataverseLookupLabel(raw, mapping.dataverseField);
        }
      } else if (mapping.type === "yesnoBoolean") {
        var raw_value = raw[mapping.dataverseField];
        record[mapping.formField] = raw_value === true ? "Yes" : (raw_value === false ? "No" : "");
      } else if (mapping.type === "multiselect") {
        var rawVal = raw[mapping.dataverseField];
        if (typeof rawVal === "string" && rawVal.length > 0) {
          record[mapping.formField] = rawVal.split(";").filter(Boolean);
        } else if (Array.isArray(rawVal)) {
          record[mapping.formField] = rawVal;
        } else {
          record[mapping.formField] = [];
        }
      } else {
        record[mapping.formField] = raw[mapping.dataverseField] == null ? "" : raw[mapping.dataverseField];
      }
    });

    return record;
  }

  function cleanGuid(guid) {
    return (guid || "").replace(/[{}]/g, "");
  }

  function fetchSectionRecords(section) {
    var deferred = $.Deferred();

    if (!parentAppGuid || parentAppGuid.length <= 20) {
      deferred.reject({ message: "Parent application ID is missing." });
      return deferred.promise();
    }

    var selectFields = getDataverseSelectFields(section);
    var filter = "_cmdspp_p_sys_id_value eq " + cleanGuid(parentAppGuid) + " and statecode eq 0";
    var url = "/_api/" + section.entitySet + "?$select=" + encodeURIComponent(selectFields) + "&$filter=" + encodeURIComponent(filter);

    webapi.safeAjax({
      type: "GET", url: url, contentType: "application/json",
      headers: {
        "Accept": "application/json", "OData-MaxVersion": "4.0", "OData-Version": "4.0",
        "Prefer": 'odata.include-annotations="OData.Community.Display.V1.FormattedValue"'
      }
    }).done(function (data) {
      var rows = (data && data.value) || [];
      section.records = rows.map(function (raw) { return mapDataverseRecord(section, raw); });
      refreshGrid(section);
      deferred.resolve(section.records);
    }).fail(function (xhr) {
      section.records = [];
      refreshGrid(section);
      console.error("Failed to refresh section from Dataverse:", xhr);
      deferred.reject(xhr);
    });

    return deferred.promise();
  }

  /*
   * CREATE / UPDATE / DELETE (grid sections)
   */
  function createDataverseRecord(section, record) {
    var payload = buildPayload(section, record);
    if (parentAppGuid && parentAppGuid.length > 20) {
      payload["cmdspp_p_sys_id@odata.bind"] = "/cmdspp_p_dtl_tbs(" + cleanGuid(parentAppGuid) + ")";
    }
    payload = withCreatedByUser(payload);

    return webapi.safeAjax({
      type: "POST", url: "/_api/" + section.entitySet, contentType: "application/json", data: JSON.stringify(payload)
    }).done(function (data, textStatus, jqXHR) {
      var newId = extractIdFromResponse(jqXHR);
      if (newId) { record.dbId = newId; record.recordId = newId; }
    });
  }

  function updateDataverseRecord(section, record) {
    if (!record.dbId) return $.Deferred().resolve().promise();
    var payload = buildPayload(section, record);
    return webapi.safeAjax({
      type: "PATCH", url: "/_api/" + section.entitySet + "(" + record.dbId + ")",
      contentType: "application/json", data: JSON.stringify(payload)
    });
  }

  function deleteDataverseRecord(section, record) {
    if (!record.dbId) return $.Deferred().resolve().promise();
    return webapi.safeAjax({
      type: "PATCH", url: "/_api/" + section.entitySet + "(" + record.dbId + ")",
      contentType: "application/json", data: JSON.stringify({ statecode: 1, statuscode: 2 })
    });
  }

  function submitSectionRecords(section) {
    var deferred = $.Deferred();

    var toCreate = section.records.filter(function (r) { return r.isNew && !r.isDeleted; });
    var toUpdate = section.records.filter(function (r) { return !r.isNew && !r.isDeleted && r.isEdited; });
    var toDelete = section.records.filter(function (r) { return !r.isNew && r.isDeleted; });

    var requests = [];
    toCreate.forEach(function (r) { requests.push(createDataverseRecord(section, r)); });
    toUpdate.forEach(function (r) { requests.push(updateDataverseRecord(section, r)); });
    toDelete.forEach(function (r) { requests.push(deleteDataverseRecord(section, r)); });

    if (requests.length === 0) { deferred.resolve(); return deferred.promise(); }

    Promise.all(requests).then(function () {
      fetchSectionRecords(section).done(function () { deferred.resolve(); }).fail(function (error) { deferred.reject(error); });
    }, function (error) { deferred.reject(error); });

    return deferred.promise();
  }

  /*
   * OTHER STATE MEDICAID - single record + two child tables
   */
  function fetchOtherStateSection(section) {
    var deferred = $.Deferred();

    if (!parentAppGuid || parentAppGuid.length <= 20) {
      deferred.reject({ message: "Parent application ID is missing." });
      return deferred.promise();
    }

    var selectFields = getDataverseSelectFields(section);
    var filter = "_cmdspp_p_sys_id_value eq " + cleanGuid(parentAppGuid) + " and statecode eq 0";
    var url = "/_api/" + section.entitySet + "?$top=1&$select=" + encodeURIComponent(selectFields) + "&$filter=" + encodeURIComponent(filter);

    webapi.safeAjax({
      type: "GET", url: url, contentType: "application/json",
      headers: { "Accept": "application/json", "OData-MaxVersion": "4.0", "OData-Version": "4.0" }
    }).done(function (data) {
      var rows = (data && data.value) || [];

      if (rows.length > 0) {
        section.record = mapDataverseRecord(section, rows[0]);
      } else {
        section.record = { recordId: null, dbId: null, isNew: true };
        (section.fields || []).forEach(function (f) {
          section.record[f.name] = Array.isArray(f.value) ? [] : "";
        });
      }

      section.savedRecord = JSON.parse(JSON.stringify(section.record));

      waitForForm(section.containerId, function (form) { form.setValues(section.record); });
      deferred.resolve();
    }).fail(function (xhr) {
      section.record = { recordId: null, dbId: null, isNew: true };
      console.error("Failed to load Other State Medicaid record:", xhr);
      deferred.reject(xhr);
    });

    return deferred.promise();
  }

  function submitOtherStateSection(section) {
    var deferred = $.Deferred();
    var record = section.record;
    var payload = buildPayload(section, record);

    if (record.isNew) {
      if (parentAppGuid && parentAppGuid.length > 20) {
        payload["cmdspp_p_sys_id@odata.bind"] = "/cmdspp_p_dtl_tbs(" + cleanGuid(parentAppGuid) + ")";
      }
      payload = withCreatedByUser(payload);

      webapi.safeAjax({
        type: "POST", url: "/_api/" + section.entitySet, contentType: "application/json", data: JSON.stringify(payload)
      }).done(function (data, textStatus, jqXHR) {
        var newId = extractIdFromResponse(jqXHR);
        if (newId) { record.dbId = newId; record.isNew = false; }
        deferred.resolve();
      }).fail(function (err) { deferred.reject(err, payload); });

    } else {
      webapi.safeAjax({
        type: "PATCH", url: "/_api/" + section.entitySet + "(" + record.dbId + ")",
        contentType: "application/json", data: JSON.stringify(payload)
      }).done(function () { deferred.resolve(); })
        .fail(function (err) { deferred.reject(err, payload); });
    }

    return deferred.promise();
  }

  function describePersistError(err, payload) {
    var boundFields = Object.keys(payload).filter(function (k) { return k.indexOf("@odata.bind") > -1; });
    var serverMsg = (err && err.responseJSON && err.responseJSON.error && err.responseJSON.error.message) || "";
    if (/permission/i.test(serverMsg) && /cmdspp_r_vv_tb/i.test(serverMsg)) {
      return "Missing Dataverse permission on cmdspp_r_vv_tb. This save tried to link: " +
        boundFields.join(", ") +
        ". Check that the portal Web Role has 'Append To' privilege on cmdspp_r_vv_tb (Global scope).";
    }
    return serverMsg || "This record could not be saved.";
  }

  /*
   * CONTINUE
   * FIX: requireRecord check now excludes isDeleted rows, and both the
   */
  function continueGridSection(section) {
    var activeRecords = section.records.filter(function (r) { return !r.isDeleted; });

    if (section.requireRecord && activeRecords.length === 0) {
      showSectionMessage(section, "Please add at least one record before continuing.", true);
      return;
    }

    showSectionMessage(section, "", false);
    setSectionLoading(section.submitBtnId, true);
    submitSectionRecords(section).done(function () {
    cmdsppUpdateApplicationProgress({
    recordId: parentAppGuid,
    pageTitle: "Provider-Identifier-Number",
    pageNumber: 3
});
      setSectionLoading(section.submitBtnId, false);
      markSectionCompleted(section.sectionId);

      if (section.nextSectionId) {
        openAccordionSection(section.nextSectionId);
      } else if (section.nextPageUrl) {
        window.location.href = section.nextPageUrl + window.location.search;
      }
    }).fail(function (error) {
      console.error("Section save failed:", error);
      setSectionLoading(section.submitBtnId, false);
      showSectionMessage(section, "Some records could not be saved. Please try again.", true);
    });
  }

  function continueSingleRecordSection(section) {
    waitForForm(section.containerId, function (form) {
      Object.assign(section.record, form.getValues());
      if (!form.validate()) return;

      showSectionMessage(section, "", false);
      setSectionLoading(section.submitBtnId, true);
      submitOtherStateSection(section).done(function () {
        fetchOtherStateSection(section).always(function () {
          setSectionLoading(section.submitBtnId, false);
          markSectionCompleted(section.sectionId);

          if (section.nextSectionId) {
            openAccordionSection(section.nextSectionId);
          } else if (section.nextPageUrl) {
            window.location.href = section.nextPageUrl + window.location.search;
          }
        });
      }).fail(function (err, failedPayload) {
        console.error("Other State Medicaid save failed:", err, failedPayload);
        setSectionLoading(section.submitBtnId, false);
        showSectionMessage(section, describePersistError(err, failedPayload || {}), true);
      });
    });
  }

  function continueSection(section) {
    if (section.isSingleRecord) continueSingleRecordSection(section);
    else continueGridSection(section);
  }

  function bindContinueButtons() {
    $(document)
      .off("click.cmdsppContinue", ".btn-continue-custom")
      .on("click.cmdsppContinue", ".btn-continue-custom", function (e) {
        e.preventDefault();
        e.stopPropagation();

        var sectionId = this.getAttribute("data-current");
        var section = getSectionByElementId(sectionId);
        if (!section) { console.error("Section not found:", sectionId); return; }

        continueSection(section);
      });
  }

  /*
   * BACK BUTTONS
   */
  document.querySelectorAll(".btn-back-custom").forEach(function (button) {
    button.addEventListener("click", function (e) {
      var target = e.currentTarget.dataset.previous || "section-dea";
      openAccordionSection(target);
    });
  });

  /*
   * INITIALIZE
   */
  function initializePage() {
    pageJson.forEach(function (section) { refreshGrid(section); });

    bindResetButtons();
    bindContinueButtons();
    bindAccordion();

    pageJson.forEach(function (section) {
      disableAddUntilReady(section);
      loadSectionOptionsMap(section);

      var loadPromise = section.isSingleRecord ? fetchOtherStateSection(section) : fetchSectionRecords(section);

      loadPromise.done(function () {
        refreshGrid(section);
      }).fail(function (error) {
        console.error("Initial Dataverse fetch failed:", section.sectionId, error);
      });
    });
  }

  initializePage();

})();
</script>"
}
